import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Inline CUDA code for a custom ReLU implementation
relu_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h>

__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = val > 0 ? val : 0.0f;
    }
}

torch::Tensor relu_forward_cuda(torch::Tensor input){
    // Ensure input is on CUDA
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    auto size = input.numel();
    auto output = torch::empty_like(input);

    const int threads = 256;
    const int blocks = (size + threads - 1) / threads;

    // Launch kernel
    relu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);

    return output;
}
"""

relu_cpp_source = r"""
torch::Tensor relu_forward_cuda(torch::Tensor input);
"""

# Build the custom ReLU extension
custom_relu = load_inline(
    name="custom_relu",
    cpp_sources=relu_cpp_source,
    cuda_sources=relu_cuda_source,
    functions=["relu_forward_cuda"],
    verbose=False
)

# Simple wrapper module around the custom ReLU
class CustomReLU(nn.Module):
    def forward(self, x):
        return custom_relu.relu_forward_cuda(x)

# Modified FireModule that uses the custom ReLU
class FireModuleNew(nn.Module):
    def __init__(self, in_channels, squeeze_channels, expand1x1_channels, expand3x3_channels):
        super(FireModuleNew, self).__init__()
        self.squeeze = nn.Conv2d(in_channels, squeeze_channels, kernel_size=1)
        self.expand1x1 = nn.Conv2d(squeeze_channels, expand1x1_channels, kernel_size=1)
        self.expand3x3 = nn.Conv2d(squeeze_channels, expand3x3_channels, kernel_size=3, padding=1)
        self.relu = CustomReLU()

    def forward(self, x):
        x = self.relu(self.squeeze(x))
        return torch.cat([
            self.relu(self.expand1x1(x)),
            self.relu(self.expand3x3(x))
        ], 1)

# Optimized Model using the custom FireModuleNew and custom ReLU
class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(3, 96, kernel_size=7, stride=2)
        self.relu = CustomReLU()
        self.maxpool1 = nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True)

        self.fire1 = FireModuleNew(96, 16, 64, 64)
        self.fire2 = FireModuleNew(128, 16, 64, 64)
        self.fire3 = FireModuleNew(128, 32, 128, 128)
        self.maxpool2 = nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True)

        self.fire4 = FireModuleNew(256, 32, 128, 128)
        self.fire5 = FireModuleNew(256, 48, 192, 192)
        self.fire6 = FireModuleNew(384, 48, 192, 192)
        self.fire7 = FireModuleNew(384, 64, 256, 256)
        self.maxpool3 = nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True)

        self.fire8 = FireModuleNew(512, 64, 256, 256)

        self.classifier = nn.Sequential(
            nn.Dropout(p=0.0),
            nn.Conv2d(512, num_classes, kernel_size=1),
            CustomReLU(),
            nn.AdaptiveAvgPool2d((1, 1))
        )

    def forward(self, x):
        x = self.conv1(x)
        x = self.relu(x)
        x = self.maxpool1(x)
        x = self.fire1(x)
        x = self.fire2(x)
        x = self.fire3(x)
        x = self.maxpool2(x)
        x = self.fire4(x)
        x = self.fire5(x)
        x = self.fire6(x)
        x = self.fire7(x)
        x = self.maxpool3(x)
        x = self.fire8(x)
        x = self.classifier(x)
        return torch.flatten(x, 1)

def get_inputs():
    return [torch.randn(1, 3, 224, 224).cuda()]

